-- Quest26706: ten missing native route groups, 48 points.
-- Pinned ArkCORE-NG a7304c3075bf8ee7eb5bdf45f31cda01c8626b52; hashes in manifest.
-- 4375101 is WORLD coordinates; 43566*,4356701,4371301 are TRANSPORT offsets.
-- Preserve whole existing groups, including custom/partial routes. No deletes.
DROP TEMPORARY TABLE IF EXISTS `_1kycore_endgame_routes`;
CREATE TEMPORARY TABLE `_1kycore_endgame_routes` LIKE waypoint_data;
SELECT src.id,src.point,src.position_x,src.position_y,src.position_z,src.orientation,
 src.delay,src.move_type,src.action,src.action_chance,src.wpguid
FROM `_1kycore_endgame_routes` src
WHERE NOT EXISTS (SELECT 1 FROM waypoint_data existing WHERE existing.id=src.id)
 AND (
  (src.id=4375101 AND EXISTS (SELECT 1 FROM creature_template ct WHERE ct.entry=43751
   AND ct.AIName='' AND ct.ScriptName='npc_hippogryph_43751' AND ct.VehicleId=641))
  OR (src.id=4371301 AND EXISTS (SELECT 1 FROM creature_template ct WHERE ct.entry=43713
   AND ct.AIName='' AND ct.ScriptName='npc_wyvern_43713' AND ct.VehicleId=983))
  OR (src.id BETWEEN 4356601 AND 4356607 AND EXISTS (SELECT 1 FROM creature_template ct WHERE ct.entry=43566
   AND ct.AIName='' AND ct.ScriptName='npc_lorna_crowley_43566'))
  OR (src.id=4356701 AND EXISTS (SELECT 1 FROM creature_template ct WHERE ct.entry=43567 AND ct.AIName='' AND ct.ScriptName='')
   AND EXISTS (SELECT 1 FROM creature_template ct WHERE ct.entry=43566 AND ct.AIName='' AND ct.ScriptName='npc_lorna_crowley_43566'))
 );
DROP TEMPORARY TABLE `_1kycore_endgame_routes`;
